/* Live covers: creators' thumbnails cross-fading over a screenshot's clay
   covers, one cover at a time. A phone opts in with data-live="<name>" on the
   .screen holding its neutral <picture>; /img/<name>-live.webp is the same
   screen with thumbnails. No JS, reduced motion, Save-Data, ?covers=off or a
   failed sheet leave the neutral picture alone. */
(function () {
  "use strict";
  /* covers:begin (generated by Scripts/make_web_screenshots.py; clip-path insets: top right bottom left) */
  var COVERS = {"library":["32.44% 51.00% 51.92% 4.17%","57.13% 51.00% 27.22% 4.17%","57.13% 4.17% 27.22% 51.00%"]};
  /* covers:end */
  var HOLD = 3.6, FADE = 1, GAP = 0.2, FIRST = 0.6; // seconds

  if (new URLSearchParams(location.search).get("covers") === "off") return;
  if (window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  if (navigator.connection && navigator.connection.saveData) return;

  var css = document.createElement("style");
  css.textContent =
    "[data-live]{position:relative}" +
    "[data-live]>img.live-cover{position:absolute;inset:0;width:100%;height:100%;max-width:none;" +
    "opacity:0;pointer-events:none;animation-timing-function:ease-in-out;" +
    "animation-iteration-count:infinite;animation-fill-mode:both}" +
    "[data-live].live-paused>img.live-cover{animation-play-state:paused}" +
    "@media (prefers-reduced-motion:reduce){[data-live]>img.live-cover{display:none}}";
  document.head.appendChild(css);

  function start(screen) {
    var name = screen.getAttribute("data-live"), clips = COVERS[name] || [];
    var picture = screen.querySelector("picture");
    if (!clips.length || !picture) return;
    // Each cover holds a state for HOLD seconds; a fade starts every `step`
    // and ends before the next one starts.
    var step = HOLD / clips.length, fade = Math.min(FADE, step - GAP);
    var at = function (s) { return (s / (2 * HOLD) * 100).toFixed(3) + "%"; };
    var sheet = new Image();
    sheet.src = "/img/" + name + "-live.webp";
    (sheet.decode ? sheet.decode() : Promise.reject()).then(function () {
      css.textContent += "@keyframes live-" + name + "{0%{opacity:0}" + at(fade) + ",50%{opacity:1}" +
        at(HOLD + fade) + ",100%{opacity:0}}";
      var anchor = picture; // layers go between the picture and the island
      clips.forEach(function (clip, i) {
        var layer = sheet.cloneNode();
        layer.className = "live-cover";
        layer.alt = "";
        layer.setAttribute("aria-hidden", "true");
        layer.style.clipPath = "inset(" + clip + ")";
        layer.style.animationName = "live-" + name;
        layer.style.animationDuration = 2 * HOLD + "s";
        layer.style.animationDelay = (FIRST + i * step).toFixed(2) + "s";
        anchor.after(layer);
        anchor = layer;
      });
      // Paused off screen, or by a tap on the phone; all layers together.
      var away = false, held = false;
      var apply = function () { screen.classList.toggle("live-paused", away || held); };
      if ("IntersectionObserver" in window) {
        new IntersectionObserver(function (e) { away = !e[e.length - 1].isIntersecting; apply(); }).observe(screen);
      }
      screen.addEventListener("click", function () { held = !held; apply(); });
    }, function () {});
  }

  function go() { Array.prototype.forEach.call(document.querySelectorAll("[data-live]"), start); }
  if (document.readyState === "complete") go(); else addEventListener("load", go);
})();
